import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}
","/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}

/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
 *  implementation runs on the server, in the browser and on the edge. */
export function newId(): string {
  const bytes = new Uint8Array(RANDOM_LENGTH);
  globalThis.crypto.getRandomValues(bytes);
  let cursor = 0;
  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
}

export function isUlid(value: string): boolean {
  return ULID_PATTERN.test(value);
}

/**
 * A deterministic id generator for tests and the seed script: same seed,
 * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so
 * fixtures are byte-stable across runs.
 */
export function idFactory(seed: number): () => string {
  let state = (seed | 0) || 0x2545_f491;
  let counter = 0;

  const next = (): number => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return Math.abs(state);
  };

  return () => {
    counter += 1;
    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.
    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);
  };
}
","/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}
